import configparser
import csv
import json
import os
import re
import sys
from datetime import date, datetime, timedelta, timezone
from decimal import Decimal

DAYS = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]


def cents(text):
    return int((Decimal(text.strip().lstrip("$")) * 100).to_integral_value())


def pnum(text):
    digits = re.sub(r"\D", "", text or "")
    return int(digits) if digits else 0


def parse_offset(text):
    text = text.strip()
    sign = -1 if text.startswith("-") else 1
    hours, minutes = text.lstrip("+-").split(":")
    return sign * (int(hours) * 60 + int(minutes))


def parse_date(text):
    return date.fromisoformat(text.strip())


def read_csv(path):
    with open(path, encoding="utf-8-sig", newline="") as handle:
        return list(csv.DictReader(handle))


def load_policy(path):
    parser = configparser.ConfigParser(interpolation=None)
    parser.optionxform = str.lower
    with open(path, encoding="utf-8-sig") as handle:
        parser.read_file(handle)
    policy = {"items": {}, "cats": {}}
    stm = parser["statement"]
    policy["library"] = stm["library"].strip()
    policy["start"] = parse_date(stm["period_start"])
    policy["end"] = parse_date(stm["period_end"])
    clock = parser["clock"]
    policy["offset"] = parse_offset(clock["offset"])
    changes = []
    for part in clock.get("changes", "").split(";"):
        part = part.strip()
        if not part:
            continue
        instant, offset = part.split()
        moment = datetime.strptime(instant, "%Y-%m-%dT%H:%MZ")
        changes.append((moment, parse_offset(offset)))
    changes.sort()
    policy["changes"] = changes
    for name in parser.sections():
        kind, _, label = name.partition(":")
        sec = parser[name]
        if kind == "item":
            policy["items"][label.strip().lower()] = {
                "name": label.strip(),
                "loan_days": int(sec["loan_days"]),
                "renewals": int(sec["renewals"]),
                "grace": int(sec["grace_days"]),
                "daily": cents(sec["daily"]),
                "loan_cap": cents(sec["loan_cap"]),
            }
        elif kind == "category":
            cap = sec["statement_cap"].strip()
            policy["cats"][label.strip().lower()] = {
                "name": label.strip(),
                "cap": None if cap.lower() == "none" else cents(cap),
                "discount": int(sec["discount"]),
                "exempt": {
                    x.strip().lower()
                    for x in sec.get("exempt", "").split(",")
                    if x.strip()
                },
            }
    return policy


def local_time(policy, event):
    if event.get("time"):
        return datetime.strptime(event["time"].strip(), "%Y-%m-%d %H:%M")
    text = event["at"].strip()
    if text.endswith(("Z", "z")):
        text = text[:-1] + "+00:00"
    moment = datetime.fromisoformat(text)
    if moment.tzinfo is None:
        moment = moment.replace(tzinfo=timezone.utc)
    utc = moment.astimezone(timezone.utc).replace(tzinfo=None)
    offset = policy["offset"]
    for change, new_offset in policy["changes"]:
        if change <= utc:
            offset = new_offset
    return utc + timedelta(minutes=offset)


def read_events(input_dir):
    folder = os.path.join(input_dir, "exports")
    events = {}
    for name in sorted(os.listdir(folder)):
        path = os.path.join(folder, name)
        if not os.path.isfile(path):
            continue
        if name.endswith(".csv"):
            rows = read_csv(path)
        elif name.endswith(".jsonl"):
            rows = []
            with open(path, encoding="utf-8-sig") as handle:
                for line in handle:
                    if line.strip():
                        rows.append(json.loads(line))
        else:
            continue
        for row in rows:
            row = {
                key: (value.strip() if isinstance(value, str) else value)
                for key, value in row.items()
                if key is not None
            }
            if row.get("event") and row["event"] not in events:
                events[row["event"]] = row
    return events


class Calendar:
    def __init__(self, input_dir):
