        for row in read_csv(os.path.join(input_dir, "branches.csv")):
            names = row["open_days"].split()
            self.open_days[row["branch"].strip()] = {
                DAYS.index(n[:3].title()) for n in names
            }
        self.rows = {}
        for row in read_csv(os.path.join(input_dir, "calendar.csv")):
            text = row["date"].strip()
            first, _, last = text.partition("..")
            first_day = parse_date(first)
            last_day = parse_date(last) if last else first_day
            key = row["branch"].strip()
            self.rows.setdefault(key, []).append(
                (first_day, last_day, row["status"].strip().lower() == "open")
            )

    def is_open(self, branch, day):
        for key in (branch, "*"):
            for first, last, status in self.rows.get(key, []):
                if first <= day <= last:
                    return status
        return day.weekday() in self.open_days.get(branch, set())

