                row["loan"].strip(),
                None if value.lower() == "full" else cents(value),
            )
        )

    events = read_events(input_dir)
    cancelled = {
        ev["target"]
        for ev in events.values()
        if ev.get("type", "").lower() == "void" and ev.get("target")
    }
    checkouts = {}
    later = {}
    for ev in events.values():
        kind = ev.get("type", "").lower()
        if ev["event"] in cancelled or kind == "void":
            continue
        ev["_local"] = local_time(policy, ev)
        if kind == "checkout":
            checkouts[ev["loan"]] = ev
        elif kind in ("renew", "return"):
            later.setdefault(ev["loan"], []).append((ev["_local"], kind, ev))

    loans = []
    for loan_id, co in checkouts.items():
        checkout_day = co["_local"].date()
        if checkout_day > end:
            continue
        item = policy["items"][co["item_type"].lower()]
        branch = co["branch"]
        due = calendar.next_open(
            branch, checkout_day + timedelta(days=item["loan_days"])
        )
        renewals = 0
        returned = None
        for moment, kind, ev in sorted(later.get(loan_id, []), key=lambda x: x[0]):
            day = moment.date()
            if kind == "renew":
                if day <= due and renewals < item["renewals"] and day <= end:
                    renewals += 1
                    due = calendar.next_open(
                        branch, day + timedelta(days=item["loan_days"])
                    )
            else:
                returned = day
                if ev.get("via", "").lower() == "dropbox":
                    returned -= timedelta(days=1)
                break
        if returned is not None and returned < start:
            continue
        if returned is not None and returned > end:
            returned = None
        end_day = returned if returned is not None else end
        overdue = 0
        day = due + timedelta(days=1)
        while day <= end_day:
            if calendar.is_open(branch, day):
                overdue += 1
            day += timedelta(days=1)
        if overdue == 0:
            continue
        key = pnum(co["patron"])
        charged = overdue if overdue > item["grace"] else 0
        cat = category(key, checkout_day)
        fee = charged * item["daily"]
        if item["name"].lower() in cat["exempt"]:
            fee = 0
        fee = min(fee, item["loan_cap"])
        assessed = (fee * (100 - cat["discount"]) + 50) // 100
        loans.append(
            {
                "key": key,
                "loan": loan_id,
                "item": co["item"],
                "item_type": item["name"],
                "branch": branch,
                "checkout": checkout_day.isoformat(),
                "due": due.isoformat(),
                "returned": returned.isoformat() if returned else None,
                "overdue_days": overdue,
                "charged_days": charged,
                "assessed": assessed,
            }
        )

    by_patron = {}
    for loan in loans:
        by_patron.setdefault(loan["key"], []).append(loan)

    statements = []
    for key in sorted(by_patron):
        group = by_patron[key]
        for loan in group:
            applying = [
                w for w in waivers if w[0] == key and w[1] in ("*", loan["loan"])
            ]
            if any(w[2] is None for w in applying):
                waived = loan["assessed"]
            else:
                waived = min(loan["assessed"], sum(w[2] for w in applying))
            loan["waived"] = waived
            loan["net"] = loan["assessed"] - waived
            loan["capped"] = 0
        cap = category(key, end)["cap"]
        if cap is not None:
            excess = sum(l["net"] for l in group) - cap
            order = sorted(group, key=lambda l: (l["due"], l["loan"]), reverse=True)
            for loan in order:
                if excess <= 0:
                    break
                give = min(excess, loan["net"])
                loan["capped"] = give
                excess -= give
        for loan in group:
            loan["billed"] = loan["net"] - loan["capped"]
        group.sort(key=lambda l: (l["due"], l["loan"]))
        fields = ("assessed", "waived", "capped", "billed")
        statement = {
            "patron": patron_names[key],
            "category": category(key, end)["name"],
            "loans": [
                {
                    k: v
                    for k, v in loan.items()
                    if k not in ("key", "net")
                }
                for loan in group
            ],
        }
        for field in fields:
            statement[field] = sum(l[field] for l in group)
        statements.append(statement)

    summary = []
    for row in read_csv(os.path.join(input_dir, "branches.csv")):
        branch = row["branch"].strip()
        mine = [l for l in loans if l["branch"] == branch]
        entry = {"branch": branch, "loans": len(mine)}
        for field in ("charged_days", "assessed", "waived", "capped", "billed"):
            entry[field] = sum(l[field] for l in mine)
        summary.append(entry)

    result = {
        "library": policy["library"],
        "period": {"start": start.isoformat(), "end": end.isoformat()},
        "statements": statements,
        "branches": summary,
    }
    with open(output_file, "w", encoding="utf-8") as handle:
        json.dump(result, handle, indent=2)
        handle.write("\n")


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
